(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,blocks=[...document.querySelectorAll('.story>section')];if(reduce||!window.gsap)return;document.documentElement.classList.add('motion-ready');const reveal=el=>gsap.to(el,{autoAlpha:1,y:0,duration:.72,ease:'power2.out',overwrite:true});const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){reveal(entry.target);observer.unobserve(entry.target)}}),{threshold:.1,rootMargin:'0px 0px -7%'});blocks.forEach(block=>observer.observe(block));gsap.from('.hero-inner',{autoAlpha:0,y:24,duration:.9,ease:'power3.out'})})();
